   ========================================= */

/* Обертка */
.find-doctor-form .consent-box {
    margin-top: 15px !important; /* Отступ сверху от полей */
    width: 100% !important;
}

/* CF7 оборачивает всё в тег p. НЕ СКРЫВАЕМ его, а делаем flex-контейнером */
.find-doctor-form .consent-box p {
