    line-height: 1.4 !important;
    text-align: left !important;
}

/* Убиваем скрытые пустые переносы строк br */
.find-doctor-form .consent-box br {
    display: none !important;
}

/* Делаем обертки CF7 компактными */
.find-doctor-form .consent-box .wpcf7-form-control-wrap,
.find-doctor-form .consent-box .wpcf7-acceptance,
.find-doctor-form .consent-box .wpcf7-list-item,
.find-doctor-form .consent-box label {
    display: flex !important;
    align-items: center !important;
    margin: 0 !important;
    padding: 0 !important;
    width: auto !important;
}

/* 
   САМ КВАДРАТИК: 
