*/
.find-doctor-form .consent-box input[type="checkbox"] {
    display: block !important;
    opacity: 1 !important; 
    visibility: visible !important; 
    position: static !important; 
    margin: 0 10px 0 0 !important; /* Отступ 10px справа до текста */
    width: 16px !important;
    height: 16px !important;
    flex: 0 0 16px !important; 
    cursor: pointer !important;
    
    appearance: none !important; 
    -webkit-appearance: none !important;
    
    background-color: transparent !important;
    border: 1px solid #870001 !important; /* Красная обводка */
    border-radius: 0 !important; /* Прямые углы */
    transition: all 0.2s ease !important;
}

/* Рисуем красную галочку, когда чекбокс нажат */
.find-doctor-form .consent-box input[type="checkbox"]:checked {
