   ФОРМА КОНСУЛЬТАЦИИ (ДВА ПОЛЯ В РЯД)
   ========================================= */

/* Отлепляем всю форму от левого и правого края экрана/колонки */
.custom-consult-form {
    padding: 0 15px !important; 
    width: 100% !important;
    box-sizing: border-box !important;
}

/* Жестко задаем сетку для полей и кнопки */
.custom-consult-form .row {
    display: flex !important;
    flex-wrap: wrap !important;
    margin: 0 -10px !important; 
}

/* Два поля выстраиваем в один ряд (по 50% ширины) */
.custom-consult-form .col-md-6 {
    flex: 0 0 50% !important;
    max-width: 50% !important;
    padding: 0 10px !important;
    margin-bottom: 20px !important; 
}

/* Кнопку растягиваем на всю ширину под полями */
.custom-consult-form .col-md-12 {
    flex: 0 0 100% !important;
    max-width: 100% !important;
    padding: 0 10px !important;
}

/* Сбрасываем лишние отступы Contact Form 7 */
.custom-consult-form p,
.custom-consult-form .frm-control {
    margin: 0 !important;
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
    box-shadow: none !important;
}

.custom-consult-form span.wpcf7-form-control-wrap {
    padding: 0 !important;
    margin: 0 !important;
    display: block !important;
    height: auto !important;
}

/* Поля ввода: белый текст и полупрозрачная белая нижняя линия */
.custom-consult-form input[type="text"],
.custom-consult-form input[type="tel"] {
    width: 100% !important;
    height: 52px !important;
    padding: 0 10px !important;
    background: transparent !important;
    border: none !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.4) !important;
    border-radius: 0 !important;
    color: #ffffff !important;
    font-size: 14px !important;
    box-shadow: none !important;
    outline: none !important;
}

/* Красим плейсхолдеры (подсказки) тоже в белый цвет, чтобы читалось на синем фоне */
.custom-consult-form input[type="text"]::placeholder,
.custom-consult-form input[type="tel"]::placeholder {
    color: rgba(255, 255, 255, 0.7) !important;
}

.custom-consult-form input[type="text"]:focus,
.custom-consult-form input[type="tel"]:focus {
    border-bottom-color: #ffffff !important;
    box-shadow: none !important;
}

/* Кнопка: без заливки, с белой обводкой и без скруглений */
.custom-consult-form .theme-btn {
    background-color: transparent !important;
    border: 2px solid #ffffff !important;
    color: #ffffff !important;
    width: 100% !important;
    height: 52px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    padding: 0 15px !important;
    font-size: 14px !important;
    font-weight: 600 !important;
    border-radius: 0 !important; /* Убрали скругление углов */
    cursor: pointer;
    box-shadow: none !important;
    text-transform: uppercase !important;
    transition: background-color 0.3s ease, border-color 0.3s ease, color 0.3s ease !important;
}

/* При наведении кнопка заливается красным */
.custom-consult-form .theme-btn:hover {
    background-color: #870001 !important;
    border-color: #870001 !important;
    color: #ffffff !important;
}

/* Глушим любые иконки внутри кнопки */
.custom-consult-form .theme-btn i,
.custom-consult-form .theme-btn span,
.custom-consult-form .theme-btn::after,
.custom-consult-form .theme-btn::before {
    display: none !important;
}

/* Адаптив для мобильных устройств: поля выстраиваются в столбец */
@media (max-width: 768px) {
    .custom-consult-form .col-md-6 {
        flex: 0 0 100% !important;
        max-width: 100% !important;
    }
}
/* =========================================
   ЧЕКБОКС СОГЛАСИЯ НА ОБРАБОТКУ ДАННЫХ (АДАПТИВНЫЙ)
   ========================================= */

/* Обертка */
.custom-consult-form .consent-box {
    margin-bottom: 20px !important; 
    width: 100% !important;
}

/* CF7 оборачивает всё в тег p. Делаем его flex-контейнером с переносом */
.custom-consult-form .consent-box p {
    display: flex !important;
    flex-wrap: wrap !important; /* Разрешаем тексту корректно переноситься на мобилках */
    align-items: flex-start !important; /* Галочка фиксируется по верхнему краю первой строки */
    margin: 0 !important;
    color: #ffffff !important; 
    font-size: 13px !important;
    line-height: 1.4 !important;
    text-align: left !important;
}

/* Убиваем скрытые пустые переносы строк br */
.custom-consult-form .consent-box br {
    display: none !important;
